-- The owner asked to control accounts, not just list them. A block flag lives on the account, and a
-- usage row is what makes "per account usage" and "what do people ask it" answerable at all: the app
-- sends one row per finished turn, and only while its own telemetry setting is on.
-- The meta table holds the key that signs the app's session tokens; it is generated by the Worker on
-- its first sign-in and never leaves the database, so a block cannot be worked around with a forged one.

ALTER TABLE accounts ADD COLUMN blocked INTEGER NOT NULL DEFAULT 0;
ALTER TABLE accounts ADD COLUMN blocked_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE accounts ADD COLUMN blocked_by TEXT NOT NULL DEFAULT '';
ALTER TABLE accounts ADD COLUMN last_used INTEGER NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS usage (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  status TEXT NOT NULL,
  prompt TEXT NOT NULL DEFAULT '',
  tools INTEGER NOT NULL DEFAULT 0,
  seconds INTEGER NOT NULL DEFAULT 0,
  plan TEXT NOT NULL DEFAULT '',
  platform TEXT NOT NULL DEFAULT '',
  version TEXT NOT NULL DEFAULT '',
  at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS usage_email_idx ON usage (email, at DESC);
CREATE INDEX IF NOT EXISTS usage_at_idx ON usage (at DESC);

CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
